### Create an Agent
# @name Create
POST {{host}}/agents
Authorization: Bearer {{token}}
x-api-key-external: {{x-api-key-external}}
Content-Type: application/json
Accept: application/json

{
  "preview_name": "string",
  "preview_description": "string",
  "presenter": {
    "type": "talk",
    "voice": {
      "type": "microsoft",
      "voice_id": "en-US-JennyNeural",
      "voice_config": {},
      "language": "English (United States)"
    },
    "source_url": "string",
    "thumbnail": "string",
    "stitch": true
  },
  "llm": {
    "provider": "openai",
    "instructions": "string",
    "template": "rag-grounded",
    "prompt_customization": {
      "role": "Salesperson",
      "personality": "string",
      "topics_to_avoid": [
        "Politics",
        "Religion"
      ],
      "max_response_length": 75,
      "knowledge_source": "base_knowledge",
      "prompt_knowledge": "string"
    },
    "temperature": 0,
    "model": "gpt-4o-global"
  },
  "knowledge": {
    "id": "string"
  },
  "starter_message": [
    "string"
  ],
  "greetings": [
    "string"
  ],
  "user_data": "string",
  "embed": true,
  "triggers": {
    "chat/end": {
      "webhooks": []
    }
  }
}

## Responses
# 200
# Description: OK
# Content-Type: application/json
# 401
# Description: AuthorizationError
# Content-Type: application/json

